<?php require __DIR__.'/includes/header.php';$cid=currentCompanyId();$rows=db()->query('SELECT p.*,w.name_en worker_name,pr.name_en project_name FROM permits p LEFT JOIN workers w ON w.id=p.worker_id LEFT JOIN projects pr ON pr.id=p.project_id'.($cid?' WHERE p.company_id='.(int)$cid:'').' ORDER BY p.id DESC')->fetchAll();?><h1><?=t('permits')?></h1><section class="card table-wrap"><table><thead><tr><th>#</th><th><?=t('workers')?></th><th><?=t('projects')?></th><th><?=t('status')?></th><th>Method</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['worker_name'])?></td><td><?=e($r['project_name'])?></td><td><?=e($r['status'])?></td><td><?=e($r['entry_method'])?></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
